import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import crypto from 'node:crypto';
import * as esbuild from 'esbuild';

const here=path.dirname(fileURLToPath(import.meta.url));
const root=path.resolve(here,'../../..');
const dest=path.join(root,'web/assets/vendor/codemirror');
const sha=data=>crypto.createHash('sha256').update(data).digest('hex');
const lockBytes=fs.readFileSync(path.join(here,'package-lock.json'));
const lock=JSON.parse(lockBytes);
const entry=fs.readFileSync(path.join(here,'entry.mjs'));
const buildScript=fs.readFileSync(fileURLToPath(import.meta.url));
const expectedExports=['Annotation','Compartment','Decoration','EditorSelection','EditorState','EditorView','GutterMarker','RangeSetBuilder','StateEffect','StateField','Transaction','WidgetType','drawSelection','dropCursor','gutter','keymap','lineNumbers'];
const result=await esbuild.build({absWorkingDir:here,entryPoints:['entry.mjs'],bundle:true,write:false,outfile:'codemirror.js',format:'iife',globalName:'NetworkToolkitCodeMirror',platform:'browser',target:['es2020'],minify:true,charset:'utf8',legalComments:'none',metafile:true,sourcemap:false,banner:{js:'/* CodeMirror 6 state/view core. MIT; see LICENSES.txt and SOURCE.json. Offline bundle; generated by scripts/vendor/codemirror/build.mjs. */'}});
const bundle=Buffer.from(result.outputFiles[0].contents);
const names=[...new Set(Object.keys(result.metafile.inputs).filter(p=>p.startsWith('node_modules/')).map(p=>p.split('/').slice(1,p.split('/')[1].startsWith('@')?3:2).join('/')))].sort();
const packages=names.map(name=>{
 const prefix='node_modules/'+name,pkg=JSON.parse(fs.readFileSync(path.join(here,prefix,'package.json'))),meta=lock.packages[prefix];
 if(!meta||meta.version!==pkg.version||!meta.resolved.startsWith('https://registry.npmjs.org/')||!/^sha512-/.test(meta.integrity)||pkg.license!=='MIT')throw Error('Unexpected package provenance: '+name);
 const license=fs.readFileSync(path.join(here,prefix,'LICENSE'),'utf8');
 return {name,version:pkg.version,license:'MIT',repository:typeof pkg.repository==='string'?pkg.repository:pkg.repository?.url,tarball:meta.resolved,integrity:meta.integrity,licenseSHA256:sha(license),licenseText:license};
});
if(names.includes('esbuild')||names.some(n=>n.startsWith('@codemirror/')&&!['@codemirror/state','@codemirror/view'].includes(n)))throw Error('Unexpected runtime package');
const licenses='Network Toolkit offline CodeMirror core runtime notices\n\n'+packages.map(p=>'===== '+p.name+' '+p.version+' =====\n'+p.licenseText.trim()+'\n').join('\n');
const buildLicense=fs.readFileSync(path.join(here,'node_modules/esbuild/LICENSE.md'),'utf8');
const platformNames=Object.entries(lock.packages).filter(([name])=>name.startsWith('node_modules/@esbuild/')).map(([name,p])=>name.slice(13)+' '+p.version).sort();
const buildNotices='Build-only dependency notices (not included in browser runtime)\n\n'+['esbuild '+esbuild.version,...platformNames].join('\n')+'\n\nAll listed platform executables are distributions of esbuild, licensed under the following MIT license:\n\n'+buildLicense;
const source={description:'Offline, core-only CodeMirror state/view bundle. No merge/diff, file access, credentials, CDN or runtime module loading.',global:'NetworkToolkitCodeMirror',exports:expectedExports,bundler:{name:'esbuild',version:esbuild.version,format:'iife',platform:'browser',target:'es2020',minify:true,sourcemap:false},inputs:{entrySHA256:sha(entry),lockSHA256:sha(lockBytes),buildScriptSHA256:sha(buildScript)},packages:packages.map(({licenseText,...rest})=>rest),artifacts:{'codemirror.js':{bytes:bundle.length,sha256:sha(bundle)},'LICENSES.txt':{bytes:Buffer.byteLength(licenses),sha256:sha(licenses)}}};
const outputs=new Map([[path.join(dest,'codemirror.js'),bundle],[path.join(dest,'LICENSES.txt'),Buffer.from(licenses)],[path.join(dest,'SOURCE.json'),Buffer.from(JSON.stringify(source,null,2)+'\n')],[path.join(here,'BUILD_LICENSES.txt'),Buffer.from(buildNotices)]]);
const check=process.argv.includes('--check');
for(const [file,data] of outputs){if(check){if(!fs.existsSync(file)||!fs.readFileSync(file).equals(data))throw Error('Generated vendor file differs: '+path.relative(root,file));}else{fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,data);}}
console.log(JSON.stringify({verified:check,bytes:bundle.length,sha256:sha(bundle),packages:packages.map(p=>p.name+'@'+p.version)}));
